            class="w-[3px] transition-all"
            style={{
              height: `${4 + i * 2}px`,
              background: lit
                ? "var(--color-vermilion)"
                : "var(--color-paper-3)",
            }}
          />
        );
      })}
    </span>
  );
}

function MicIcon() {
  return (
