    >
      <rect
        x="9"
        y="2"
        width="6"
        height="12"
        rx="3"
        fill="currentColor"
        stroke="none"
      />
      <path d="M5 11a7 7 0 0 0 14 0" />
      <path d="M12 18v3" />
    </svg>
  );
}
