import { GroundedNote } from "../personas/grounded-note";
import { NoteEvidenceList } from "../personas/note-evidence-list";
import { component$, type PropFunction } from "@qwik.dev/core";
import { renderMarkdown } from "../../utils/markdown";
import { revealQuoteFromEvent } from "../../utils/quote-grounding";
import { SpeakButton } from "../ui/speak-button";
import { ChatComposer } from "../ui/chat-composer";
import { PersonaPortrait } from "../personas/persona-portrait";
import type { NotePopover } from "./editor-state";
import { openLiveVoice } from "../../utils/live-voice-workspace";

interface PersonaNotePanelProps {
  note: NotePopover | null;
  onPin$: PropFunction<(noteId: string) => void>;
  onClose$: PropFunction<() => void>;
  onReply$: PropFunction<
    (noteId: string, text: string, author: string) => void
  >;
  onStrike$: PropFunction<(noteId: string) => void>;
  /** Drafts set without an input event, such as a dictated reply. */
  onDraft$?: PropFunction<(noteId: string, draft: string) => void>;
}

/**
 * The anchored conversation with a persona about one marked passage.
 *
 * The face and the card's colour already say who is speaking, and the marked
 * passage sits right beside the card, so neither name, role, label nor quote
 * is repeated here: the note's words get the room. Talking is the first way
 * to answer, listening the second, typing the fallback.
 */
export const PersonaNotePanel = component$<PersonaNotePanelProps>((props) => {
  const note = props.note;
  const onPin$ = props.onPin$;
  const onClose$ = props.onClose$;
  const onReply$ = props.onReply$;
  const onStrike$ = props.onStrike$;
  const onDraft$ = props.onDraft$;

  if (!note) return null;

  return (
    <div
      class={[
        "persona-note-card manuscript-comment-card",
        { "is-in-margin": !!note.margin },
      ]}
      data-margin-item={note.margin ?? undefined}
      role="dialog"
      aria-label={`Note from ${note.author}`}
      style={{
        left: `${note.x}px`,
        top: note.top != null ? `${note.top}px` : "auto",
        bottom: note.bottom != null ? `${note.bottom}px` : "auto",
        "max-height": `${note.maxH}px`,
        width: note.width ? `${note.width}px` : undefined,
        "--comment-color": note.color,
      }}
      onClick$={(event) => {
        event.stopPropagation();
        if (!note.pinned) onPin$(note.id);
      }}
      onMouseLeave$={(event) => {
        if (note.pinned || note.replying || note.thread.length > 0) return;
        const related = (event as MouseEvent)
          .relatedTarget as HTMLElement | null;
        if (related?.closest(".twyne-persona-note")) return;
        if (related?.closest(".twyne-mark-anchor")) return;
        onClose$();
      }}
    >
      <div class="persona-note__bar">
        <button
          type="button"
          class="persona-note__face focus-ring"
          aria-label={`Talk with ${note.author} about this note`}
          title={`Talk with ${note.author}`}
          onClick$={() => openLiveVoice(note.author, note.note)}
        >
          <PersonaPortrait name={note.author} size={40} />
        </button>
        <button
          type="button"
          class="persona-note__talk focus-ring"
          aria-label={`Talk with ${note.author} about this note`}
          title={`Talk with ${note.author}`}
          onClick$={() => openLiveVoice(note.author, note.note)}
        >
          <MicIcon />
          <span aria-hidden="true">Talk</span>
        </button>
        <SpeakButton
          labelled
          class="persona-note__listen"
          id={`note-popover-${note.id}`}
          text={note.note}
          author={note.author}
          label={note.author}
        />
        <span class="flex-1" />
        <button
          type="button"
          onClick$={() => onStrike$(note.id)}
          class="persona-note__strike focus-ring"
          title="Strike — mark as addressed"
        >
          Strike
        </button>
        <button
          type="button"
          onClick$={onClose$}
          class="manuscript-comment-card__close persona-note__close"
          aria-label="Close note"
        >
          ✕
        </button>
      </div>

      <div class="manuscript-comment-card__body persona-note__body">
        <GroundedNote
          data-speech-id={`note-popover-${note.id}`}
          class="comment-markdown persona-note__text"
          onClick$={(event: Event) => revealQuoteFromEvent(event)}
          text={note.note}
        />
        <NoteEvidenceList evidence={note.evidence} context={note.note} />

        {note.thread.length > 0 && (
          <div class="persona-note-thread space-y-2">
            {note.thread.map((reply) =>
              reply.authorKind === "user" ? (
                <WriterThreadReply key={reply.id} text={reply.text} />
              ) : (
                <PersonaThreadReply
                  key={reply.id}
                  personaId={reply.personaId}
                  author={reply.author}
                  noteAuthor={note.author}
                  text={reply.text}
                  color={note.color}
                />
              ),
            )}
          </div>
        )}

        {note.replying && note.streamingReply.trim() && (
          <div class="persona-note-streaming flex justify-start">
            <PersonaReplyBubble text={note.streamingReply} color={note.color} />
          </div>
        )}
        {note.replying && !note.streamingReply.trim() && (
          <div class="persona-note-typing" role="status">
            <span class="typing-dots" aria-hidden="true">
              <span>.</span>
              <span>.</span>
              <span>.</span>
            </span>
            <span class="sr-only">{`${note.author} is replying`}</span>
          </div>
        )}
        {note.error && (
          <p
            class="persona-note-error text-[0.7rem] leading-4 text-[var(--color-vermilion)]"
            style={{ fontFamily: "var(--font-typewriter)" }}
          >
            {note.error}
          </p>
        )}
      </div>

      <div class="persona-note__composer">
        <ChatComposer
          value={note.draft}
          onValueChange$={(draft) => onDraft$?.(note.id, draft)}
          onSend$={() => onReply$(note.id, note.draft, note.author)}
          busy={note.replying}
          placeholder="Or write back…"
          label={`Reply to ${note.author}`}
          sendLabel="Reply"
          transcriptionHint={note.author}
          inputData={{
            "data-thread-draft-kind": "note",
            "data-thread-draft-id": note.id,
          }}
        />
      </div>
    </div>
  );
});

function MicIcon() {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="1.8"
      stroke-linecap="round"
      aria-hidden="true"
    >
      <rect
        x="9"
        y="2"
        width="6"
        height="12"
        rx="3"
        fill="currentColor"
        stroke="none"
      />
      <path d="M5 11a7 7 0 0 0 14 0" />
      <path d="M12 18v3" />
    </svg>
  );
}

const WriterThreadReply = component$<{ text: string }>(({ text }) => (
  <div class="flex justify-end" data-author-kind="user">
    <div
      class="persona-note__bubble persona-note__bubble--writer comment-markdown whitespace-pre-wrap"
      dangerouslySetInnerHTML={renderMarkdown(text)}
    />
  </div>
));

/** A face only when someone other than the note's author joins in. */
const PersonaThreadReply = component$<{
  personaId?: string;
  author: string;
  noteAuthor: string;
  text: string;
  color: string;
}>(({ personaId, author, noteAuthor, text, color }) => (
  <div class="flex items-end justify-start gap-1.5" data-author-kind="persona">
    {author !== noteAuthor && (
      <span title={author} class="flex-shrink-0">
        <PersonaPortrait personaId={personaId} name={author} size={24} />
      </span>
    )}
    <PersonaReplyBubble text={text} color={color} />
  </div>
));

const PersonaReplyBubble = component$<{ text: string; color: string }>(
  ({ text, color }) => (
    <div
      class="persona-note__bubble persona-note__bubble--persona"
      style={{ "background-color": color, "border-color": color }}
    >
      <GroundedNote
        class="comment-markdown comment-markdown-on-color whitespace-pre-wrap"
        style={{ color: "var(--color-paper)" }}
        onClick$={(event: Event) => revealQuoteFromEvent(event)}
        text={text}
      />
    </div>
  ),
);

