   The face and --comment-color name the editor, so nothing else does. */
.persona-note__bar {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 0.35rem 0.45rem 0.55rem;
  border-bottom: 1px solid var(--color-paper-3);
  background: color-mix(
    in srgb,
    var(--comment-color) 7%,
    var(--color-paper-soft)
  );
}
.persona-note__face {
  flex-shrink: 0;
  border-radius: 9999px;
  transition: box-shadow 0.15s ease;
}
.persona-note__face:hover {
  box-shadow: 0 0 0 2px var(--comment-color);
}
.persona-note__talk,
.persona-note__listen {
  display: inline-flex;
  height: 2rem;
  align-items: center;
  gap: 0.4rem;
  padding: 0 0.7rem;
  border: 1px solid var(--comment-color);
  border-radius: 2px;
  font-family: var(--font-typewriter);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
}
.persona-note__talk {
  background: var(--comment-color);
  color: var(--color-paper);
}
.persona-note__talk:hover {
  filter: brightness(1.08);
}
.persona-note__listen {
  background: var(--color-paper);
  color: var(--color-ink);
}
.persona-note__listen:hover,
.persona-note__listen[data-speech-status="playing"],
.persona-note__listen[data-speech-status="paused"] {
  background: color-mix(in srgb, var(--comment-color) 12%, var(--color-paper));
}
.persona-note__listen[data-speech-status="error"] {
  border-color: var(--color-accent-red);
  color: var(--color-accent-red);
}
